var r=`1356-ceviche-de-camaron`;var n=`world-1356`;var o=`EC`;var t=`south-america`;var a=4;var s=53;var m={en:`Ceviche de Camarón`,ua:`Севіче з креветками`};var c={en:`Ceviche de Camarón is a dish from Ecuador featuring shrimp, lime juice, orange juice, tomato. This home-sized recipe records each ingredient at the step where it is used. Shrimp are fully heat-cooked before citrus dressing for safety; regional versions vary.`,ua:`Севіче з креветками, страва кухні країни Еквадор з такими основними складниками: креветка, сік лайма, апельсиновий сік, помідор. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Креветки повністю термічно приготовано перед цитрусовою заправкою з міркувань безпеки; регіональні версії різняться.`};var l=[{en:`Fully cook shrimp until opaque and pearly, then chill promptly; citrus juice is not a replacement for cooking.`,ua:`Повністю приготуйте креветки до непрозорості, після чого швидко охолодіть; цитрусовий сік не замінює термічної обробки.`,t:[`poaching`],m:10,i:[[`shrimp`,690,`g`],[`water`,700,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`lime-juice`,135,`ml`],[`orange-juice`,100,`ml`],[`tomato`,310,`g`],[`red-onion`,170,`g`]]},{en:`Refrigerate the prepared mixture for about 30 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 30 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:30,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`cilantro`,30,`g`],[`corn-tortillas`,8,`pcs`]]}];var d={slug:r,id:n,country:`EC`,region:t,servings:4,minutes:53,title:m,text:c,steps:l};export{o as country,d as default,n as id,s as minutes,t as region,a as servings,r as slug,l as steps,c as text,m as title};